@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<PostListingBlock>>
@{
    var site = Umbraco.AssignedContentItem.AncestorOrSelf<BlogFrontPage>();
    var posts = site?.Children<BlogPost>().OrderByDescending(post => post.CreateDate)
        .Select(post => new PostCardModel
        {
            Title = post.Title ?? post.Name,
            Summary = post.Summary ?? "",
            Url = post.Url(),
            ImageUrl = post.CoverImage?.GetCropUrl(width: 900, height: 560),
            ImageAlt = post.CoverAlt ?? "",
            Date = post.CreateDate
        }).ToArray() ?? [];
    var model = new PostListingModel
    {
        Heading = Model.Content.Heading ?? "",
        Intro = Model.Content.Intro ?? "",
        Posts = posts
    };
}
@await Component.InvokeAsync("PostListing", new { model })
